CREATE TABLE IF NOT EXISTS "xray_templates" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(100) NOT NULL DEFAULT '',
    "type" VARCHAR(20) NOT NULL DEFAULT '',
    "config" JSONB NOT NULL DEFAULT '{}'::jsonb,
    "description" VARCHAR(255) NOT NULL DEFAULT '',
    "enabled" BOOLEAN NOT NULL DEFAULT TRUE,
    "created_at" TIMESTAMPTZ DEFAULT NULL,
    "updated_at" TIMESTAMPTZ DEFAULT NULL
);

CREATE INDEX IF NOT EXISTS "idx_xray_template_type" ON "xray_templates" ("type");

CREATE TABLE IF NOT EXISTS "server_xray_templates" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "server_id" BIGINT NOT NULL DEFAULT 0,
    "template_id" BIGINT NOT NULL DEFAULT 0,
    "sort" INTEGER NOT NULL DEFAULT 0,
    "enabled" BOOLEAN NOT NULL DEFAULT TRUE,
    "created_at" TIMESTAMPTZ DEFAULT NULL,
    "updated_at" TIMESTAMPTZ DEFAULT NULL,
    CONSTRAINT "uni_server_xray_template" UNIQUE ("server_id", "template_id")
);

CREATE INDEX IF NOT EXISTS "idx_server_xray_templates_server_id" ON "server_xray_templates" ("server_id");
CREATE INDEX IF NOT EXISTS "idx_server_xray_templates_template_id" ON "server_xray_templates" ("template_id");
